    imageHint: "Hisham's Palace mosaic floor and ruins Jericho",
    descriptionAdvanced: {
      de: "Der Hischam-Palast, auch als Khirbat al-Mafjar bekannt, ist eines der bedeutendsten Monumente der frühen islamischen Architektur weltweit. Etwa fünf Kilometer nördlich von Jericho gelegen, wurde die Anlage im 8. Jahrhundert während der Umayyaden-Dynastie unter Kalif Hischam ibn Abd al-Malik oder dessen Neffen Walid II. errichtet. Der Komplex umfasst einen Palast, ein prachtvolles Badehaus und eine Moschee, die alle reich mit Stukkaturen und Mosaiken verziert waren. Das berühmteste Merkmal ist das 'Baum des Lebens'-Mosaik, welches eine Gazelle zeigt, die von einem Löwen angegriffen wird – ein Symbol für Krieg und Frieden. Ein schweres Erdbeben im Jahr 749 zerstörte große Teile des Palastes, noch bevor er vollständig fertiggestellt war. Dank umfangreicher Restaurierungen, insbesondere der Überdachung des riesigen Mosaikbodens im Badehaus, ist der Ort heute ein erstklassiges Ziel für Archäologieliebhaber. Die kunstvollen Steinmetzarbeiten und das ikonische sternförmige Fenster, der sogenannte Oskulus, zeugen von der hohen handwerklichen Kunstfertigkeit der Umayyaden-Zeit.",
      hu: "A Jerikótól északra fekvő Hisám-palota az omajjád építészet egyik legfontosabb fennmaradt emléke, amely a 8. század első felében épült. A komplexum eredetileg sivatagi rezidenciának készült, amely palotát, mecsetet és egy hatalmas fürdőházat foglalt magában. A helyszín világhírét elsősorban lenyűgöző padlómozaikjainak köszönheti, amelyek közül kiemelkedik az 'Élet fája' ábrázolás. Ez a mozaik egy gazellákat és egy oroszlánt ábrázol, szimbolizálva az uralkodó hatalmát és az igazságosságot. Bár a 749-es nagy földrengés romba döntötte az épületeket még azelőtt, hogy teljesen befejezték volna őket, a romok így is hűen tükrözik a korszak luxusát és technikai fejlettségét. A látogatók ma megcsodálhatják a nemrégiben restaurált és védőtetővel ellátott fürdőcsarnokot, amelynek mozaikpadlója az egyik legnagyobb és legjobb állapotban fennmaradt a Közel-Keleten. A palota udvarán látható jellegzetes kőcsillag (okulusz) a palesztin művészet egyik legismertebb jelképévé vált, megtestesítve az iszlám művészet korai virágkorának eleganciáját.",
      ro: "Palatul lui Hisham, situat în oaza Ierihonului, reprezintă o capodoperă a arhitecturii islamice timpurii din perioada dinastică Omeiadă. Construit în secolul al VIII-lea ca reședință de iarnă și complex de vânătoare, situl este celebru pentru bogăția decorativă a mozaicurilor și a stucaturilor sale. Elementul central de atracție este mozaicul 'Arborele Vieții', situat în sala de primire a băii, care ilustrează măiestria artistică a epocii prin detalii figurative complexe. Deși complexul a fost sever afectat de cutremurul din anul 749, structurile rămase, inclusiv marea sală a băilor cu cele 38 de covoare de mozaic, au fost recent restaurate și protejate de o structură modernă, oferind vizitatorilor o experiență imersivă unică. Pe lângă valoarea artistică, palatul reflectă stilul de viață luxos al califilor omeiazi, îmbinând tradițiile bizantine cu noile influențe arabe. Faimoasa fereastră stelată din piatră, găsită printre ruine, a devenit un simbol cultural recunoscut al Palestinei, marcând continuitatea istorică și splendoarea unui imperiu care se întindea odinioară de la Atlantic până în Asia Centrală.",
      en: "Hisham's Palace, located just north of the ancient city of Jericho, is one of the most significant archaeological sites of the early Islamic Umayyad period. Built in the 8th century, likely during the reign of Caliph Hisham ibn Abd al-Malik or his successor Walid II, the complex was designed as a desert retreat featuring a palace, a mosque, and an expansive bathhouse. The site is world-renowned for its exquisite floor mosaics, most notably the 'Tree of Life' in the diwan, which depicts a lion attacking gazelles—a masterpiece of early Islamic figurative art. Although a massive earthquake in 749 AD partially destroyed the palace before its completion, the preserved ruins offer invaluable insights into the architecture and courtly life of the era. A major restoration project recently unveiled a protective roof over the bathhouse's 825-square-meter mosaic floor, allowing visitors to appreciate one of the largest and best-preserved mosaic pavements in the world. The iconic six-pointed stone star window, reconstructed from fragments, remains a symbol of Palestinian craftsmanship and the enduring legacy of Umayyad artistic brilliance.",
      es: "El Palacio de Hisham, también conocido como Khirbet al-Mafjar, es una obra maestra de la arquitectura islámica temprana cerca de Jericó. Fue construido en el siglo VIII como pabellón de caza real y complejo de baños para la dinastía omeya. El sitio es famoso por sus espectaculares suelos de mosaico y sus artísticos estucos. El mosaico más famoso muestra el 'Árbol de la Vida' y es uno de los mejor conservados de su época.",
      pt: "O Palácio de Hisham, também conhecido como Khirbet al-Mafjar, é uma obra-prima da arquitetura islâmica primitiva perto de Jericó. Foi construído no século VIII como pavilhão de caça senhorial e complexo de banhos para a dinastia Omíada. O local é famoso pelos seus espetaculares pisos de mosaico e decorações de estuque artísticas. O mosaico mais famoso mostra a 'Árvore da Vida' e é um dos mais bem preservados da sua época.",
      fr: "Le palais de Hisham, également connu sous le nom de Khirbet al-Mafjar, est un chef-d'œuvre de l'architecture islamique ancienne près de Jéricho. Il a été érigé au VIIIe siècle comme résidence de chasse et complexe de bains pour la dynastie omeyyade. Le site est célèbre pour ses sols en mosaïque spectaculaires et ses décorations en stuc raffinées. La mosaïque la plus célèbre représente l'« Arbre de Vie » et compte parmi les mieux conservées de son temps.",
    },
