      hu: ["Muszlimok és zsidók számára is szent", "Heródes-kori kőfalak övezik", "Hebron óvárosának központja", "UNESCO Világörökség része"],
      ro: ["Sfântă pentru musulmani și evrei", "Ziduri din epoca herodiană", "Centrul orașului vechi din Hebron", "Patrimoniul Mondial UNESCO"],
