      pt: ["Local de sepultamento de Abraão, Isaque, Jacó e as suas esposas", "Muralhas perimetrais com cerca de 2.000 anos da época herodiana", "Declarado Património Mundial da UNESCO em 2017", "O local está dividido em áreas muçulmana e judaica", "Considerado o quarto local mais sagrado do Islão", "As muralhas têm até 15 metros de altura"],
