      pt: ["Fundado por volta de 480 d.C. por João de Tebas", "Aspeto atual marcado pela renovação iniciada em 1878", "Abriga relíquias de São Jorge de Coziba", "A gruta do profeta Elias situa-se dentro do complexo", "Foi parcialmente destruído pelos persas em 614 d.C.", "Um caminho de cerca de 20 minutos desce da estrada"],
      fr: ["Fondé vers 480 après J.-C. par Jean de Thèbes", "Aspect actuel marqué par la rénovation commencée en 1878", "Abrite des reliques de Saint Georges de Choziba", "La grotte du prophète Élie se trouve à l'intérieur du complexe", "Partiellement détruit par les Perses en 614 après J.-C.", "Un sentier d'environ 20 minutes descend depuis la route"],
