      hu: ["Római fórum látható itt", "Oszlopsoros út maradványai", "Keresztelő Szent János nyughelye (hagyomány)", "Bizánci templomromok"],
      ro: ["Deține un forum roman", "Rămășițe ale unei străzi cu colonade", "Locul de mormânt al Sf. Ioan Botezătorul", "Ruinele unei biserici bizantine"],
      en: ["Features a Roman forum", "Remains of a colonnaded street", "Traditional burial site of John the Baptist", "Byzantine church ruins"],
      es: ["Posee un foro romano", "Restos de una calle con columnas", "Lugar de entierro de Juan el Bautista (tradición)", "Ruinas de una iglesia bizantina"],
      pt: ["Possui um fórum romano", "Restos de uma rua com colunatas", "Local de sepultamento de João Batista (tradição)", "Ruínas de uma igreja bizantina"],
