      pt: ["Fundada no século IX a.C. pelo Rei Omri", "Foi renomeada por Herodes, o Grande, em honra de Augusto", "A rua das colunatas tinha originalmente mais de 800 metros de comprimento", "Inclui os restos de uma basílica bizantina", "Local tradicional do túmulo de João Batista", "O teatro romano tinha capacidade para cerca de 3.000 espectadores"],
