      hu: ["I. sz. 329 körül alapították", "Templomokat és fürdőket foglal magába", "Tell Umm Amer területén található", "Fontos UNESCO világörökségi várományos"],
      ro: ["Fondată în jurul anului 329 d.Hr.", "Cuprinde biserici și băi", "Situată în situl Tell Umm Amer", "Silit de importanță UNESCO"],
      en: ["Founded around 329 AD", "Includes multiple churches and baths", "Located at the Tell Umm Amer site", "Significant UNESCO tentative site"],
