      es: ["Fundado hacia el 329 d.C. por San Hilarión", "El complejo abarca unos 7.500 metros cuadrados", "Incluido en la lista del Patrimonio Mundial de la UNESCO en 2024", "Contiene restos de cinco iglesias sucesivas", "Cuenta con un complejo sistema de drenaje y alcantarillado", "Fue un importante centro de peregrinación durante más de 400 años"],
      pt: ["Fundado por volta de 329 d.C. por Santo Hilarião", "O complexo abrange cerca de 7.500 metros quadrados", "Incluído na lista do Património Mundial da UNESCO em 2024", "Contém restos de cinco igrejas sucessivas", "Possui um sistema complexo de drenagem e canais", "Foi um importante centro de peregrinação durante mais de 400 anos"],
