      pt: ["Consistem em três reservatórios em diferentes níveis", "A capacidade total é de cerca de 160.000 metros cúbicos de água", "A fortaleza de Murad (otomana) foi construída em 1617 para proteção", "Ligadas ao aqueduto Qanawat para Jerusalém", "O nome refere-se ao Rei Salomão (Cântico dos Cânticos)", "O reservatório inferior tem mais de 170 metros de comprimento"],
      fr: ["Composés de trois bassins situés à des niveaux différents", "La capacité totale est d'environ 160 000 mètres cubes d'eau", "La forteresse de Mourad (ottomane) fut construite en 1617 pour les protéger", "Reliés à l'aqueduc Qanawat vers Jérusalem", "Le nom fait référence au roi Salomon (Cantique des Cantiques)", "Le bassin inférieur mesure plus de 170 mètres de long"],
