      en: ["Renovated in 1998-1999 for the new millennium", "Mosque of Omar built in 1860 on donated land", "The Peace Center was inaugurated in 1999", "Annual Christmas tree lighting ceremony site", "Square size is approximately 4,000 square meters", "Located at an elevation of 775 meters"],
      es: ["Renovación entre 1998 y 1999 para el nuevo milenio", "La Mezquita de Omar fue construida en 1860 en terrenos donados", "El Centro de la Paz fue inaugurado en 1999", "Ceremonia anual de encendido del árbol de Navidad", "El tamaño de la plaza es de unos 4.000 metros cuadrados", "Altitud de 775 metros sobre el nivel del mar"],
      pt: ["Renovação entre 1998 e 1999 para o novo milénio", "A Mesquita de Omar foi construída em 1860 em terrenos doados", "O Centro da Paz foi inaugurado em 1999", "Cerimónia anual de iluminação da árvore de Natal", "O tamanho da praça é de cerca de 4.000 metros quadrados", "Altitude de 775 metros acima do nível do mar"],
