      ro: ["Structura actuală a fost finalizată în 1872", "Păstrează fragmente de mozaic din secolul al V-lea", "Loc de pelerinaj popular pentru cuplurile care doresc copii", "Situată la mică distanță de Biserica Nașterii Domnului", "Administrată de Custodia Locurilor Sfinte", "Grota este formată din calcar moale, alb"],
      en: ["Present structure was completed in 1872", "Contains 5th-century mosaic floor remains", "Popular pilgrimage site for couples seeking fertility", "Located a short walk from the Church of the Nativity", "Managed by the Custody of the Holy Land", "The grotto is made of soft, white limestone"],
      es: ["La estructura actual se terminó en 1872", "Se conservan restos de un suelo de mosaico del siglo V", "Lugar de peregrinación popular para parejas que desean tener hijos", "Se encuentra a pocos minutos a pie de la Basílica de la Natividad", "Gestionada por la Custodia de Tierra Santa", "La gruta está formada por piedra caliza blanca y blanda"],
      pt: ["Estrutura atual concluída em 1872", "Restos de um pavimento de mosaico do século V preservados", "Local de peregrinação popular para casais que desejam ter filhos", "Situada a poucos minutos a pé da Igreja da Natividade", "Gerida pela Custódia da Terra Santa", "A gruta é composta por calcário branco macio"],
