      es: "El Campo de los Pastores en Beit Sahour marca el lugar donde los ángeles anunciaron el nacimiento de Jesús a los pastores.",
      pt: "O Campo dos Pastores em Beit Sahour marca o local onde os anjos anunciaram o nascimento de Jesus aos pastores.",
