    imageHint: "Shepherd's Field Chapel Beit Sahour Bethlehem",
    descriptionAdvanced: {
      de: "Die Hirtenfelder in Beit Sahour, unweit von Bethlehem, gelten als der Ort, an dem die Engel den Hirten die frohe Botschaft von der Geburt Jesu verkündeten. Das Gelände beherbergt eine markante Kapelle, die 1954 von dem berühmten Architekten Antonio Barluzzi entworfen wurde. Ihre zeltförmige Struktur erinnert an die Behausungen der Hirten von einst und lässt durch eine Lichtkuppel das Licht wie den Stern von Bethlehem einfallen. Neben der modernen Kapelle finden sich auf dem Areal zahlreiche natürliche Höhlen, die bereits in byzantinischer Zeit als Gebetsräume und Wohnstätten genutzt wurden. Archäologische Ausgrabungen haben Überreste eines Klosters aus dem 4. und 5. Jahrhundert freigelegt, was die lange Tradition dieses Ortes als Pilgerziel unterstreicht. Die friedliche Atmosphäre und die kunstvollen Mosaike im Inneren der Kapelle machen die Hirtenfelder zu einem der besinnlichsten Orte in der Umgebung von Bethlehem, der Geschichte und Glauben auf eindrucksvolle Weise verbindet.",
      hu: "A Betlehem melletti Beit Sahourban található Pásztorok mezeje a keresztény hagyomány egyik legkedvesebb helyszíne, ahol az angyali üdvözlet elhangzott. A terület központi eleme a Szent Angyalok-kápolna, amelyet 1954-ben Antonio Barluzzi tervezett. Az épület különleges, sátor alakú formája a nomád pásztorok hajdani hajlékaira utal, a kupolán lévő nyílásokon keresztül beáramló fény pedig a mennyei dicsőséget szimbolizálja. A kertben sétálva számos természetes barlangot láthatunk, amelyeket a korai keresztények templomként vagy menedékként használtak; ezekben ma is láthatók bizánci kori mozaikok és kőoltárok. A régészeti feltárások egy 4. századi kolostor romjait is felszínre hozták, bizonyítva, hogy a helyszín már az ókor végén is fontos zarándokhely volt. A csendes ligetek és a bibliai táj látványa különleges spirituális élményt nyújt az ide látogatóknak, felidézve a karácsonyi történet egyszerű, vidéki kezdetét.",
      ro: "Câmpul Păstorilor din localitatea Beit Sahour este un sit de o importanță spirituală deosebită, situat la mică distanță de Betleem. Conform tradiției, acesta este locul unde îngerii s-au arătat păstorilor pentru a le vesti nașterea lui Mesia. Elementul central al sitului este capela proiectată de arhitectul Antonio Barluzzi în 1954, a cărei formă exterioară evocă un cort de nomazi. Interiorul este luminat natural printr-o cupolă perforată, creând o atmosferă care sugerează prezența divină. Pe lângă edificiul modern, vizitatorii pot explora peșteri naturale care au servit drept locuințe și biserici în perioada bizantină, păstrând urme de mozaicuri vechi și altare cioplite în piatră. Săpăturile arheologice au scos la iveală fundațiile unui complex monahal din secolele IV-V, confirmând vechimea pelerinajelor în această zonă. Grădinile liniștite și peisajul colinar oferă un cadru perfect pentru reflecție, fiind o oprire esențială pentru oricine vizitează locurile sfinte din regiune.",
      en: "Shepherd's Field in Beit Sahour, just east of Bethlehem, is traditionally revered as the site where angels appeared to the shepherds to announce the birth of Jesus. The highlight of the site is the Chapel of the Angels, designed in 1954 by the renowned architect Antonio Barluzzi. Its unique tent-shaped structure is a symbolic nod to the dwellings of local shepherds, while the interior is bathed in natural light from a skylight, mimicking the celestial glow of the angelic visitation. The grounds are scattered with natural limestone caves that have been used for habitation and worship since the Byzantine era, some containing ancient mosaics and altars. Archaeological research has uncovered the remains of a 4th-century monastery and press, indicating the site's long-standing religious importance. Today, the peaceful site serves as a place of pilgrimage and quiet meditation, offering stunning views of the surrounding hills and a direct link to the pastoral roots of the Nativity story.",
      es: "La capilla del Campo de los Pastores en Beit Sahour conmemora el lugar donde los ángeles anunciaron el nacimiento de Jesús. Fue diseñada en 1953 por el arquitecto Antonio Barluzzi y tiene forma de tienda nómada. En su interior se encuentran frescos que representan los acontecimientos bíblicos. El lugar también incluye cuevas naturales que antiguamente servían de refugio.",
      pt: "A Capela do Campo dos Pastores em Beit Sahour comemora o local onde os anjos anunciaram o nascimento de Jesus. A capela foi projetada em 1953 pelo arquiteto Antonio Barluzzi e tem a forma de uma tenda nómada. No interior, existem frescos que representam os eventos bíblicos. O local também inclui grutas naturais que outrora serviam de abrigo.",
      fr: "La chapelle du Champ des Bergers à Beit Sahour commémore le lieu où les anges ont annoncé la naissance de Jésus. La chapelle a été conçue en 1953 par l'architecte Antonio Barluzzi et a la forme d'une tente nomade. L'intérieur abrite des fresques illustrant les événements bibliques. Le site comprend également des grottes naturelles qui servaient autrefois d'abris.",
    },
