      en: ["Architect Antonio Barluzzi designed the chapel in 1953", "The building resembles a Bedouin tent", "Features three bronze statues of shepherds", "Consecrated on April 11, 1954", "Archaeological evidence shows habitation since Bronze Age", "Located about 2 kilometers east of Bethlehem"],
      es: ["El arquitecto Antonio Barluzzi diseñó la capilla en 1953", "El edificio recuerda a una tienda beduina", "Incluye tres estatuas de bronce de pastores", "Consagrada el 11 de abril de 1954", "Hallazgos arqueológicos demuestran asentamientos desde la Edad del Bronce", "Se encuentra a unos 2 kilómetros al este de Belén"],
      pt: ["O arquiteto Antonio Barluzzi projetou a capela em 1953", "O edifício assemelha-se a uma tenda beduína", "Inclui três estátuas de bronze de pastores", "Consagrada em 11 de abril de 1954", "Achados arqueológicos comprovam povoamento desde a Idade do Bronze", "Localizado a cerca de 2 quilómetros a leste de Belém"],
