    imageHint: "Mount Gerizim archaeological site ruins Nablus",
    descriptionAdvanced: {
      de: "Der Berg Gerizim, der sich südlich der Stadt Nablus erhebt, ist für die Gemeinschaft der Samariter der heiligste Ort der Erde. Die archäologische Stätte auf dem Gipfel beherbergt die Überreste eines samaritanischen Tempels aus der persischen und hellenistischen Zeit, der im 5. Jahrhundert durch eine massive byzantinische Kirche ersetzt wurde. Im Gegensatz zum jüdischen Glauben, der den Tempelberg in Jerusalem als Zentrum sieht, betrachten die Samariter den Gerizim als den wahren Ort des göttlichen Heiligtums. Noch heute lebt eine kleine Gemeinde im Dorf Kiryat Luza am Hang des Berges und praktiziert hier jährlich das traditionelle Pessach-Opfer nach jahrtausendealten Riten. Die Ausgrabungen zeigen zudem beeindruckende Verteidigungsanlagen und römische Strukturen. Neben seiner religiösen Bedeutung bietet der Gipfel einen strategischen Panoramablick über das biblische Sichem und das moderne Nablus, was die historische Rolle des Berges als Wächter über die zentralen Handelswege des Landes unterstreicht.",
      hu: "A Nabulusz városától délre emelkedő Gerizim-hegy a szamaritánus közösség számára a föld legszentebb helye. A csúcson található régészeti lelőhely egy perzsa és hellenisztikus korból származó szamaritánus templom maradványait őrzi, amelyet az 5. században egy hatalmas bizánci templommal váltottak fel. Ellentétben a zsidó hagyománnyal, amely a jeruzsálemi Templom-hegyet tekinti központnak, a szamaritánusok szerint a Gerizim az isteni szentély valódi helyszíne. Ma is él egy kis szamaritánus közösség a hegyoldalban fekvő Kiryat Luza faluban, ahol minden évben megtartják a hagyományos húsvéti áldozatot több ezer éves rítusok szerint. Az ásatások során impozáns védőfalak és római kori építmények is felszínre kerültek. Vallási jelentősége mellett a csúcs stratégiai panorámát kínál a bibliai Sikemre és a modern Nabuluszra, hangsúlyozva a hegy történelmi szerepét a régió központi kereskedelmi útvonalainak ellenőrzésében.",
      ro: "Muntele Garizim, situat la sud de orașul Nablus, este considerat de comunitatea samariteană cel mai sfânt loc de pe pământ. Situl arheologic de pe culme adăpostește vestigiile unui templu samaritean din perioadele persană și elenistică, peste care a fost construită în secolul al V-lea o impunătoare biserică bizantină dedicată Maicii Domnului. Spre deosebire de tradiția iudaică, ce are centrul spiritual la Ierusalim, samarietenii cred că Garizim este locul ales pentru sanctuarul divin. Astăzi, o mică comunitate trăiește încă în satul Kiryat Luza de pe versantul muntelui, unde practică anual sacrificiul de Paște conform unor ritualuri milenare. Excavațiile au scos la iveală și fortificații masive, precum și structuri din perioada romană. Pe lângă importanța sa spirituală, muntele oferă o vedere panoramică strategică asupra orașului antic Sihem și a Nablusului modern, subliniind rolul istoric al înălțimii ca punct de observație asupra rutelor comerciale centrale din regiune.",
      en: "Mount Gerizim, rising south of the city of Nablus, is revered as the holiest site on earth by the Samaritan community. The archaeological complex at its summit features the significant remains of a Samaritan temple from the Persian and Hellenistic periods, which was later supplanted in the 5th century by a massive Byzantine church. While mainstream Jewish tradition focuses on the Temple Mount in Jerusalem, Samaritans maintain that Gerizim is the true location of the divine sanctuary mentioned in the Torah. Today, a vibrant yet small Samaritan community resides in the village of Kiryat Luza on the mountain's slope, where they continue to perform the annual Passover sacrifice according to ancient rites. Excavations have revealed impressive fortification walls and Roman-era ruins that attest to the site's strategic value. Beyond its religious weight, the peak offers sweeping panoramic views over biblical Shechem and modern Nablus, highlighting its historical role as a sentinel over the region's central crossroads.",
      es: "El monte Gerizim es la montaña sagrada de los samaritanos y alberga importantes excavaciones arqueológicas. En la cima se encuentran restos de un templo samaritano y de una iglesia bizantina del siglo V. El lugar ofrece una vista panorámica de la ciudad de Naplusa y sus alrededores. Para la comunidad samaritana, este es el lugar más sagrado del mundo.",
      pt: "O monte Gerizim é a montanha sagrada dos samaritanos e abriga importantes escavações arqueológicas. No cume encontram-se restos de um templo samaritano e de uma igreja bizantina do século V. O local oferece uma vista panorâmica da cidade de Nablus e dos arredores. Para a comunidade samaritana, este é o local mais sagrado do mundo.",
      fr: "Le mont Garizim est la montagne sacrée des Samaritains et abrite d'importantes fouilles archéologiques. Au sommet se trouvent les restes d'un temple samaritain et d'une église byzantine du Ve siècle. Le site offre une vue panoramique sur la ville de Naplouse et ses environs. Pour la communauté samaritaine, c'est le lieu le plus sacré au monde.",
    },
