      fr: ["L'altitude du sommet est de 881 mètres au-dessus du niveau de la mer", "L'église byzantine a été construite en 484 après J.-C.", "Vestiges d'un temple samaritain du Ve siècle avant J.-C.", "Foyer d'une petite communauté samaritaine", "Lieu du sacrifice annuel de la Pâque des Samaritains", "Le parc archéologique a été aménagé dans les années 1990"],
