      de: ["Nahe dem Jakobsbrunnen gelegen", "Heilig für Muslime, Juden und Christen", "Kuppelbau im osmanischen Stil", "Oft Ort politischer Spannungen"],
      hu: ["Jákob kútja közelében fekszik", "Muszlimok, zsidók és keresztények számára is szent", "Oszmán stílusú kupolás épület", "Gyakori politikai feszültségek helyszíne"],
      ro: ["Situat lângă Fântâna lui Iacob", "Sfânt pentru musulmani, evrei și creștini", "Edificiu cu cupolă în stil otoman", "Loc de tensiuni politice frecvente"],
      en: ["Located near Jacob's Well", "Sacred to Muslims, Jews, and Christians", "Ottoman-style domed structure", "Often a flashpoint for regional tensions"],
