    imageHint: "Joseph's Tomb Nablus domed building",
    descriptionAdvanced: {
      de: "Das Josefsgrab liegt am östlichen Rand von Nablus, unweit des historischen Jakobsbrunnens, und ist eine der bedeutendsten religiösen Stätten der Region. Das heutige Bauwerk ist ein kleiner, weiß getünchter Kuppelbau im osmanischen Stil, der über einer antiken Grabkammer errichtet wurde. Traditionell wird der Ort als die Begräbnisstätte des biblischen Patriarchen Josef, dem Sohn Jakobs, verehrt. Die Stätte ist für Muslime, Juden und Christen gleichermaßen heilig und wird in zahlreichen religiösen Schriften erwähnt. Über die Jahrhunderte hinweg war das Grab Ziel unzähliger Pilger, wurde jedoch in der jüngeren Geschichte immer wieder zum Schauplatz politischer und religiöser Spannungen. Trotz dieser Konflikte bleibt es ein Symbol für die tiefe Verwurzelung der abrahamitischen Religionen in der Landschaft von Samaria. Der Besuch der Stätte erfordert aufgrund der Sicherheitslage oft eine Koordination, doch die historische und spirituelle Aura des Ortes zieht weiterhin Menschen aus aller Welt an, die hier eine Verbindung zur biblischen Geschichte suchen.",
      hu: "József sírja Nabulusz keleti szélén, Jákob kútjának közvetlen közelében található, és a térség egyik legfontosabb vallási emlékhelye. A jelenlegi építmény egy jellegzetes, fehérre meszelt, oszmán stílusú kupolás épület, amely egy ősi sírkamra felett áll. A hagyomány szerint itt nyugszik a bibliai József pátriárka, Jákob fia, akit mind a zsidó, mind a keresztény, mind a muszlim vallás tisztel. A helyszín évszázadok óta fontos zarándokhely, ahol a látogatók a bibliai időkig visszanyúló történelmi folytonosságot érezhetik. Sajnálatos módon a sírhely a modern korban gyakran válik politikai és vallási feszültségek gyújtópontjává, ami miatt látogatása esetenként korlátozott. Ennek ellenére építészeti megjelenése és spirituális jelentősége továbbra is kiemelkedő. A sírbolt környéke a régészeti kutatások számára is érdekes, hiszen a terület az ókori Sikem városának közelében fekszik, amely központi szerepet játszott a pátriárkák történeteiben.",
      ro: "Mormântul lui Iosif este situat la marginea estică a orașului Nablus, în apropierea Fântânii lui Iacov, fiind un loc de o profundă încărcătură spirituală. Structura actuală este o clădire modestă cu cupolă, ridicată în stil otoman, care marchează locul unde, conform tradiției, odihnește patriarhul biblic Iosif, fiul lui Iacov. Acest monument este venerat de secole de către evrei, creștini și musulmani, fiind menționat în numeroase texte religioase și istorice. De-a lungul timpului, situl a servit drept loc de pelerinaj, dar a fost și centrul unor dispute intense din cauza semnificației sale religioase simbolice. Arhitectura sa simplă, tipică pentru mausoleele din perioada otomană, contrastează cu istoria tumultuoasă a locației. Vizitatorii care ajung aici pot resimți legătura directă cu narațiunile biblice desfășurate în regiunea Samaria. Deși accesul poate fi uneori dificil din motive de securitate, mormântul rămâne un punct de referință crucial pentru patrimoniul religios al Palestinei și pentru istoria patriarhilor.",
      en: "Joseph's Tomb is located on the eastern outskirts of Nablus, situated near the ancient Jacob's Well. The site features an Ottoman-style domed structure that has served as a focal point for religious devotion for centuries. Traditionally identified as the burial place of the biblical patriarch Joseph, son of Jacob, the tomb is revered across Muslim, Jewish, and Christian traditions. Its historical significance is deeply rooted in religious texts, which describe the return of Joseph's remains from Egypt to be buried in Shechem. Throughout its long history, the tomb has been a place of pilgrimage, though in recent decades it has frequently become a flashpoint for regional political tensions. Despite these conflicts, the structure remains an architectural testament to the region's Ottoman heritage and a symbol of shared, yet contested, religious history. For many, a visit to this site represents a profound connection to the narratives of the Old Testament and the enduring spiritual landscape of the West Bank.",
      es: "La Tumba de José en Naplusa es considerada tradicionalmente como el lugar de enterramiento del patriarca bíblico José. El edificio actual data del siglo XIX y se caracteriza por una cúpula blanca. El lugar tiene una gran importancia para judíos, samaritanos, cristianos y musulmanes. Se encuentra en la entrada este de Naplusa, cerca del campo de refugiados de Balata.",
      pt: "O Túmulo de José em Nablus é tradicionalmente considerado o local de sepultamento do patriarca bíblico José. O edifício atual data do século XIX e é caracterizado por uma cúpula branca. O local é de grande importância para judeus, samaritanos, cristãos e muçulmanos. Situa-se na entrada leste de Nablus, perto do campo de refugiados de Balata.",
      fr: "Le tombeau de Joseph à Naplouse est traditionnellement considéré comme le lieu de sépulture du patriarche biblique Joseph. Le bâtiment actuel date du XIXe siècle et se caractérise par un dôme blanc. Le site revêt une grande importance pour les juifs, les samaritains, les chrétiens et les musulmans. Il est situé à l'entrée est de Naplouse, à proximité du camp de réfugiés de Balata.",
    },
