    imageHint: "Kur Throne Village stone palaces Palestine",
    descriptionAdvanced: {
      de: "Kur ist ein außergewöhnliches Beispiel für ein palästinensisches „Thron-Dorf“ (Throne Village) und liegt im nördlichen Westjordanland südlich von Tulkarm. Diese Dörfer dienten während der osmanischen Ära als Sitze lokaler Steuereintreiber und Herrscherfamilien, was sich in der beeindruckenden Architektur widerspiegelt. Das Ortsbild von Kur wird von massiven, palastartigen Residenzen, den sogenannten Qasrs, dominiert, die im 18. und 19. Jahrhundert vom Jayyusi-Klan erbaut wurden. Diese befestigten Steinbauten mit ihren dicken Mauern, kunstvollen Portalen und weiten Innenhöfen zeugen vom einstigen Reichtum und der Macht der lokalen Herrscher. Das Dorf liegt exponiert auf einem Hügel, was ihm eine strategische Verteidigungsposition und einen weiten Blick über die fruchtbaren Täler der Umgebung verschaffte. Heute ist Kur ein bedeutendes Denkmal der palästinensischen Sozialgeschichte und Architektur, das trotz des Verfalls vieler Gebäude seinen majestätischen und wehrhaften Charakter bewahrt hat.",
      hu: "Kur egyedülálló történelmi emlékhely Ciszjordánia északi részén, Tulkarm közelében. A település az úgynevezett palesztin „trónfalvak” (Throne Villages) egyike, amelyek az oszmán korszakban a helyi adószedők és uralkodó klánok székhelyeként szolgáltak. Kur képét a Jayyusi-klán által épített monumentális, palotaszerű kőházak, az úgynevezett „qasrok” határozzák meg. Ezek az erődített udvarházak vastag falaikkal, díszes kapuikkal és belső udvaraikkal a 18. és 19. századi helyi hatalom és gazdagság jelképei. A falu egy dombtetőre épült, ami egykor stratégiai védelmi előnyt jelentett, ma pedig lenyűgöző kilátást nyújt a környező olajfaligetekre és völgyekre. Kur építészeti öröksége a palesztin társadalomtörténet fontos darabja, ahol a látogatók testközelből tapasztalhatják meg az oszmán-kori feudális építészet monumentalitását és a mészkőből faragott paloták időtlen szépségét.",
      ro: "Kur este un exemplu remarcabil de „sat palatin” (Throne Village) palestinian, situat în nordul Cisiordaniei, în apropiere de Tulkarm. Aceste sate au funcționat în perioada otomană ca centre administrative și reședințe ale clanurilor dominante care colectau taxe în numele imperiului. Arhitectura satului Kur este dominată de „qasrs” – conace fortificate masive construite din piatră de către clanul Jayyusi în secolele XVIII și XIX. Aceste structuri impunătoare, cu ziduri groase, porți boltite și curți interioare largi, reflectă puterea și bogăția de odinioară a conducătorilor locali. Poziționat pe vârful unui deal, satul oferea o vedere strategică asupra văilor înconjurătoare, fiind ușor de apărat. Astăzi, Kur reprezintă un sit de o importanță istorică și arhitecturală deosebită, oferind vizitatorilor o călătorie în timp prin structurile sale medievale bine conservate, care spun povestea sistemului social și politic din Palestina otomană.",
      en: "Kur is an extraordinary example of a Palestinian 'Throne Village', located in the northern West Bank south of Tulkarm. During the Ottoman era, these villages served as the administrative seats of powerful local clans who acted as tax collectors and regional rulers. The skyline of Kur is defined by its massive, palace-like stone residences known as 'qasrs', built primarily by the influential Jayyusi clan during the 18th and 19th centuries. These fortified manor houses feature thick limestone walls, arched gateways, and spacious courtyards, symbolizing the wealth and authority of the feudal lords of the time. Situated atop a hill for strategic defense, the village offers sweeping views of the surrounding olive groves and terraced landscapes. Today, Kur stands as a significant cultural heritage site, preserving a unique architectural style that blends domestic comfort with defensive necessity, providing a rare window into the social hierarchy of Ottoman-era Palestine.",
      es: "Kur es uno de los llamados 'pueblos del trono' (Qura al-Karasi) en Palestina, conocido por su monumental arquitectura otomana. Fue la sede del clan Jayyousi, que controló la región durante siglos. El pueblo está formado por palacios tipo fortaleza y casas señoriales de piedra de los siglos XVIII y XIX. La arquitectura refleja el poder y la riqueza de la familia gobernante local.",
      pt: "Kur é uma das chamadas 'aldeias do trono' (Qura al-Karasi) na Palestina, conhecida pela sua arquitetura otomana monumental. Foi a sede do clã Jayyousi, que controlou a região durante séculos. A aldeia consiste em palácios semelhantes a fortalezas e casas senhoriais de pedra dos séculos XVIII e XIX. A arquitetura reflete o poder e a riqueza da família governante local.",
      fr: "Kur est l'un des « villages du trône » (Qura al-Karasi) de Palestine, connu pour son architecture ottomane monumentale. C'était le siège du clan Jayyousi, qui a contrôlé la région pendant des siècles. Le village se compose de palais aux allures de forteresses et de maisons de maître en pierre des XVIIIe et XIXe siècles. L'architecture reflète le pouvoir et la richesse de la famille régnante locale.",
    },
    factsAdvanced: {
      de: ["Eines der 24 Thron-Dörfer in Palästina", "Stammsitz des einflussreichen Jayyousi-Clans", "Hauptpaläste stammen aus dem 18. Jahrhundert", "Dorf ist auf einem Hügel strategisch angelegt", "Steinhäuser besitzen oft dicke Verteidigungsmauern", "Befindet sich in der Region Tulkarm"],
      hu: ["Egyike Palesztina 24 'trón-falujának'", "Az befolyásos Jayyousi-klán székhelye", "A fő paloták a 18. századból származnak", "A falu stratégiailag egy dombtetőre épült", "A kőházak gyakran vastag védőfalakkal rendelkeznek", "Tulkarm régiójában található"],
      ro: ["Unul dintre cele 24 de 'sate-tron' din Palestina", "Reședința clanului influent Jayyousi", "Palatele principale datează din secolul al XVIII-lea", "Satul este așezat strategic pe o colină", "Casele din piatră au ziduri groase de apărare", "Situat în regiunea Tulkarm"],
      en: ["One of the 24 'Throne Villages' in Palestine", "Ancestral seat of the influential Jayyousi clan", "Main palaces date back to the 18th century", "The village is strategically situated on a hilltop", "Stone houses often feature thick defensive walls", "Located in the Tulkarm governorate"],
      es: ["Uno de los 24 pueblos del trono en Palestina", "Sede del influyente clan Jayyousi", "Los palacios principales datan del siglo XVIII", "El pueblo está estratégicamente ubicado en una colina", "Las casas de piedra suelen tener gruesos muros defensivos", "Se encuentra en la región de Tulkarem"],
      pt: ["Uma das 24 aldeias do trono na Palestina", "Sede do influente clã Jayyousi", "Os palácios principais datam do século XVIII", "A aldeia está estrategicamente situada numa colina", "As casas de pedra têm frequentemente muros defensivos espessos", "Situa-se na região de Tulkarm"],
      fr: ["L'un des 24 villages du trône de Palestine", "Siège de l'influent clan Jayyousi", "Les palais principaux datent du XVIIIe siècle", "Le village est stratégiquement situé sur une colline", "Les maisons en pierre ont souvent d'épais murs de défense", "Se trouve dans la région de Tulkarem"],
    },
