      hu: ["A választófalra néz", "Saját múzeuma van", "Eredeti Banksy-műveket tartalmaz", "Közvetlenül a fal mellett áll"],
      ro: ["Vedere spre zidul de separare", "Adăpostește un muzeu", "Conține lucrări originale Banksy", "Situat lângă bariera de separare"],
