      es: ["Vista al muro de separación", "Alberga un museo", "Contiene obras originales de Banksy", "Situado directamente junto al muro"],
      pt: ["Vista para o muro de separação", "Abriga um museu", "Contém obras originais de Banksy", "Localizado diretamente junto ao muro"],
