      pt: ["Inauguração em 3 de março de 2017", "Os quartos contêm obras de arte originais de Banksy", "Abriga uma exposição permanente sobre a história do muro", "O hotel dispõe de um piano bar de estilo colonial", "Oferece workshops de graffiti para os visitantes", "A poucos metros do muro de betão israelita"],
