      pt: ["Inauguração em janeiro de 2011 pelo presidente Dmitry Medvedev", "O terreno abrange uma área de aproximadamente 1,2 hectares", "Inclui restos de um mosteiro bizantino", "Apresenta mosaicos dos séculos V e VI", "Foi projetado por arquitetos russos", "Situado no centro da cidade de Jericó"],
