    imageHint: "Shalom Al Yisrael Synagogue mosaic Jericho",
    descriptionAdvanced: {
      de: "Die Schalom-Al-Yisrael-Synagoge befindet sich im nordwestlichen Teil von Jericho und ist ein bedeutendes Zeugnis der jüdischen Präsenz in der Stadt während der byzantinischen Ära. Die Anlage wurde im Jahr 1936 während Ausgrabungen unter der Leitung von Dmitri Baramki entdeckt. Besonders hervorzuheben ist der prächtige Mosaikboden, der auf das späte 6. oder frühe 7. Jahrhundert datiert wird. Das zentrale Motiv des Mosaiks ist eine Menora, flankiert von einem Schofar und einem Lulav, umgeben von einem kreisförmigen Rahmen mit der hebräischen Inschrift „Friede über Israel“ (Shalom Al Yisrael), die dem Ort seinen Namen gab. Die Ruinen befinden sich heute unter dem Fundament eines privaten Wohnhauses, das zum Schutz der Fundstätte errichtet wurde. Für Besucher bietet der Ort einen faszinierenden Einblick in die religiöse Vielfalt des antiken Jerichos und die architektonische Kunstfertigkeit jener Zeit, wobei die Mosaike trotz ihres Alters in einem bemerkenswert guten Zustand erhalten geblieben sind.",
      hu: "A Shalom Al Yisrael zsinagóga Jerikó északnyugati részén található, és a bizánci korszak egyik legfontosabb zsidó építészeti emléke a térségben. A lelőhelyet 1936-ban fedezték fel véletlenül, amikor egy magánház alapozási munkálatai során rábukkantak a föld alatt rejtőző mozaikpadlóra. A 6. század végéről vagy a 7. század elejéről származó mozaik központi eleme egy hétágú gyertyatartót, azaz menórát ábrázol, amelyet egy kosszarv (sófár) és egy pálmaág (luláv) szegélyez. A díszes keretben olvasható héber felirat, a „Shalom Al Yisrael” (Béke Izraelre) adta a zsinagóga mai nevét. Az épület maradványai jelenleg egy modern lakóház pincéjében találhatók, amely segít megvédeni a finom mozaikokat az időjárás viszontagságaitól. A látogatók számára ez a helyszín különleges hidat képez a múlt és a jelen között, bemutatva a város ókori vallási életének gazdagságát és a korabeli mesterek precíz munkáját.",
      ro: "Sinagoga Shalom Al Yisrael, situată în partea de nord-vest a Ierihonului, reprezintă o dovadă arheologică prețioasă a comunității evreiești din perioada bizantină. Descoperit în mod accidental în anul 1936, situl a fost scos la lumină în timpul săpăturilor coordonate de arheologi sub fundația unei case private. Piesa centrală a complexului este pardoseala de mozaic, datând de la sfârșitul secolului al VI-lea, care a supraviețuit într-o stare de conservare remarcabilă. Mozaicul înfățișează o menora tradițională, încadrată de un șofar și un lulav, fiind înconjurat de o inscripție în limba ebraică ce urează „Pace peste Israel”. Această binecuvântare a dat și numele sub care este cunoscut astăzi lăcașul de cult. Deoarece ruinele se află sub o proprietate privată, accesul este adesea coordonat pentru a asigura protecția sitului. Este o destinație esențială pentru cei interesați de istoria religiilor și de arta mozaicului antic, oferind o perspectivă rară asupra vieții spirituale din Ierihonul de acum 1500 de ani.",
      en: "The Shalom Al Yisrael Synagogue is a significant archaeological site located in the northwestern outskirts of Jericho. Discovered in 1936 during the construction of a private residence, the ruins date back to the late 6th or early 7th century, a period when Jericho had a vibrant Jewish community. The most striking feature of the site is its beautifully preserved mosaic floor. The central panel depicts a traditional seven-branched Menorah, accompanied by a shofar (ram's horn) and a lulav (palm branch). Enclosed within a circular border is the Hebrew phrase 'Shalom Al Yisrael', meaning 'Peace unto Israel', from which the synagogue derives its modern name. Interestingly, the mosaic remains situated beneath the foundations of a private house belonging to the Shahwan family, who have helped protect the site over decades. For travelers and history enthusiasts, it offers a poignant glimpse into Byzantine-era religious architecture and the enduring cultural layers of one of the world's oldest continuously inhabited cities.",
      es: "La Sinagoga Shalom Al Yisrael en Jericó es un antiguo lugar de culto que data de finales del siglo VI o principios del VII. Fue descubierta en 1936 durante unas excavaciones y es famosa por su mosaico en el suelo, que muestra símbolos religiosos como una menorá y un shofar. La inscripción 'Paz sobre Israel' dio al lugar su nombre actual.",
      pt: "A Sinagoga Shalom Al Yisrael em Jericó é uma antiga sinagoga do final do século VI ou início do século VII. Foi descoberta em 1936 durante escavações e é famosa pelo seu mosaico no chão, que exibe símbolos religiosos como uma menorá e um shofar. A inscrição 'Paz sobre Israel' deu ao local o seu nome atual.",
      fr: "La synagogue Shalom Al Yisrael à Jéricho est une ancienne synagogue de la fin du VIe ou du début du VIIe siècle. Découverte en 1936 lors de fouilles, elle est célèbre pour sa mosaïque au sol représentant des symboles religieux tels qu'une ménorah et un shofar. L'inscription « Paix sur Israël » a donné au site son nom actuel.",
    },
    factsAdvanced: {
      de: ["Entdeckung durch den Architekten Dimitri Baramki im Jahr 1936", "Das Mosaik misst etwa 10 mal 13 Meter", "Zeigt eine Menora, ein Schofar und ein Lulav", "Die aramäische Inschrift wünscht Frieden für die Gemeinde", "Befindet sich heute unter einem privaten Wohnhaus", "Die Ausgrabung erfolgte während der britischen Mandatszeit"],
      hu: ["1936-ban fedezte fel Dimitri Baramki építész", "A mozaik mérete körülbelül 10 x 13 méter", "Menórát, sófárt és lulávot ábrázol", "Az arámi felirat békét kíván a közösségnek", "Ma egy magánház alagsorában található", "A feltárás a brit mandátum idején történt"],
      ro: ["Descoperită de arhitectul Dimitri Baramki în anul 1936", "Mozaicul măsoară aproximativ 10 pe 13 metri", "Înfățișează o menora, un șofar și un lulav", "Inscripția aramaică urează pace comunității", "Situată în prezent sub o casă privată", "Săpăturile au avut loc în perioada mandatului britanic"],
      en: ["Discovered by architect Dimitri Baramki in 1936", "The main mosaic floor measures about 10 by 13 meters", "Depicts a menorah, a shofar, and a lulav (palm branch)", "Features an Aramaic inscription blessing the community", "The site is currently located beneath a private residence", "Excavations were carried out during the British Mandate period"],
      es: ["Descubrimiento por el arquitecto Dimitri Baramki en 1936", "El mosaico mide unos 10 por 13 metros", "Muestra una menorá, un shofar y un lulav", "La inscripción aramea desea paz para la comunidad", "Se encuentra hoy bajo una vivienda privada", "La excavación se realizó durante el mandato británico"],
      pt: ["Descoberta pelo arquiteto Dimitri Baramki em 1936", "O mosaico mede cerca de 10 por 13 metros", "Mostra uma menorá, um shofar e um lulav", "A inscrição aramaica deseja paz para a comunidade", "Encontra-se hoje sob uma residência privada", "A escavação ocorreu durante o período do mandato britânico"],
      fr: ["Découverte par l'architecte Dimitri Baramki en 1936", "La mosaïque mesure environ 10 mètres sur 13", "Représente une ménorah, un shofar et un lulav", "L'inscription araméenne souhaite la paix à la communauté", "Se trouve aujourd'hui sous une maison d'habitation privée", "Les fouilles ont eu lieu pendant le mandat britannique"],
    },
