      es: ["Erigida en 1860 en terrenos donados por la Iglesia", "Renovada en 1955 durante la administración jordana", "Nombrada en honor al segundo califa islámico, Omar", "Símbolo de la convivencia pacífica en Belén", "Única mezquita directamente en la Plaza del Pesebre", "El minarete ofrece una amplia vista de la Ciudad Vieja"],
      pt: ["Erguida em 1860 em terrenos doados pela Igreja", "Renovada em 1955 durante a administração jordana", "Nomeada em honra do segundo califa islâmico, Omar", "Símbolo da coexistência pacífica em Belém", "Única mesquita diretamente na Praça da Manjedoura", "O minarete oferece uma vista ampla sobre a Cidade Velha"],
