      de: ["Restaurierte Steinhäuser", "Sitz lokaler Gouverneure", "In der Region Jenin gelegen", "Wichtige historische Architektur"],
      hu: ["Restaurált kőházak", "Helyi kormányzók székhelye volt", "Dzsenín régiójában található", "Fontos történelmi építészet"],
