    imageHint: "Arraba Throne Village palaces Jenin",
    descriptionAdvanced: {
      de: "Arraba ist eines der bedeutendsten sogenannten 'Thron-Dörfer' Palästinas, gelegen in den malerischen Hügeln des Gouvernements Jenin. Diese Dörfer waren im 18. und 19. Jahrhundert Sitze mächtiger lokaler Clans, die im Auftrag der Osmanen Steuern eintrieben und die Region verwalteten. In Arraba war es die Familie Abd al-Hadi, die hier monumentale Palastgebäude aus lokalem Kalkstein errichtete. Der historische Kern des Dorfes beeindruckt durch seine dichte osmanische Architektur, mit gewölbten Durchgängen, befestigten Mauern und kunstvoll verzierten Fassaden. Viele dieser historischen Manors wurden in den letzten Jahren aufwendig restauriert, um das kulturelle Erbe zu bewahren und den Tourismus zu fördern. Arraba bietet Besuchern die Möglichkeit, in die feudale Geschichte Palästinas einzutauchen und die traditionelle Handwerkskunst der Steinmetze zu bewundern. Neben den Palästen ist das Dorf für seine Olivenhaine und die Produktion von hochwertigem Olivenöl bekannt, was die wirtschaftliche Basis der Region seit Jahrhunderten darstellt.",
      hu: "Arraba az egyik legfontosabb 'trónfalu' Palasztinában, Dzsenín kormányzóság dombjai között fekszik. A 18. és 19. században ezek a falvak a helyi uralkodó klánok székhelyei voltak, akik az Oszmán Birodalom nevében adót gyűjtöttek és irányították a vidéket. Arrabában a befolyásos Abd al-Hadi család építette ki központját, monumentális kőpalotákat emelve, amelyek ma is meghatározzák a falu látképét. A történelmi központ szűk utcái, boltíves átjárói és erődítményszerű lakóházai a palesztin feudális építészet remekművei. Az elmúlt években jelentős restaurálási munkálatok zajlottak, így a látogatók eredeti pompájukban csodálhatják meg a faragott mészkő homlokzatokat és a tágas belső udvarokat. Arraba nemcsak építészeti kincs, hanem a mezőgazdaságáról, különösen a kiváló minőségű olívaolajáról is híres. A falu felkeresése egyedülálló lehetőséget ad a látogatóknak, hogy megismerjék az oszmán-kori közigazgatás örökségét és a palesztin vidéki élet mélyen gyökerező hagyományait.",
      ro: "Arraba este unul dintre cele mai relevante 'sate ale tronului' (Throne Villages) din Palestina, situat în regiunea colinară a guvernoratului Jenin. În perioada otomană, aceste sate serveau drept reședințe pentru clanurile nobiliare locale care exercitau autoritatea administrativă și fiscală asupra zonelor rurale. În Arraba, familia Abd al-Hadi a construit complexe palatiale impresionante, care domină și astăzi nucleul istoric al localității. Arhitectura din piatră de calcar, cu arcade largi, curți interioare și ziduri fortificate, reflectă puterea și statutul social al proprietarilor săi de odinioară. Multe dintre aceste palate au beneficiat de proiecte de restaurare atentă, fiind transformate în centre culturale sau spații comunitare care păstrează identitatea locului. Satul este renumit nu doar pentru istoria sa politică, ci și pentru producția tradițională de ulei de măsline, plantațiile de măslini înconjurând așezarea pe kilometri întregi. O vizită în Arraba oferă o incursiune autentică în feudalismul palestinian și o lecție de arhitectură otomană conservată exemplar într-un cadru natural pitoresc.",
      en: "Arraba is a prominent 'Throne Village' in Palestine, located in the northern hills of the Jenin Governorate. During the late Ottoman period (18th and 19th centuries), these villages served as the political seats for powerful rural families who acted as regional tax collectors and governors. In Arraba, the Abd al-Hadi clan built an array of monumental limestone palaces and manors that still stand today as masterpieces of vernacular architecture. The historic core of the village is a maze of arched streets, fortified houses, and ornate stone facades that showcase the wealth of the feudal era. In recent years, extensive restoration efforts have revitalized several of these palaces, converting them into cultural centers that host exhibitions and workshops. Beyond its architectural grandeur, Arraba is deeply tied to the land, famous for its high-quality olive oil production and terraced agriculture. Visiting Arraba allows travelers to step back in time and explore a unique chapter of Palestinian governance and social history, all while enjoying the scenic beauty of the Samarian highlands.",
      es: "Arraba es uno de los 'pueblos del trono' más importantes de las tierras altas palestinas y fue sede de la poderosa familia Abd al-Hadi. La arquitectura del pueblo se caracteriza por residencias palaciegas, llamadas Qasrs, construidas en los siglos XVIII y XIX. Estos edificios servían como símbolos de poder político y son hoy importantes testimonios de la administración rural otomana.",
      pt: "Arraba é uma das mais importantes 'vilas do trono' nas terras altas palestinas e foi outrora a sede da poderosa família Abd al-Hadi. A arquitetura da vila é caracterizada por residências palacianas, chamadas Qasrs, construídas nos séculos XVIII e XIX. Estes edifícios serviam como símbolos de poder político e são hoje importantes testemunhos da administração rural otomana.",
      fr: "Arraba est l'un des plus importants « villages du trône » des hauts plateaux palestiniens et fut autrefois le siège de la puissante famille Abd al-Hadi. L'architecture du village se caractérise par des résidences palatiales, appelées Qasrs, construites aux XVIIIe et XIXe siècles. Ces bâtiments servaient de symboles de pouvoir politique et sont aujourd'hui des témoignages importants de l'administration rurale ottomane.",
    },
