      pt: ["Uma das 24 vilas históricas do trono", "Sede da família Abd al-Hadi no século XIX", "Contém sete grandes complexos palacianos (Qasrs)", "Foi amplamente restaurada pela organização RIWAQ", "Os palácios serviam como centros administrativos fortificados", "Localiza-se perto da cidade de Jenin"],
