    parent: "PS",
    type: "landmark",
    name: { de: "Khan el-Zeit", hu: "Khan el-Zeit", ro: "Khan el-Zeit", en: "Khan el-Zeit" },
    coords: [35.2306, 31.7803],
    description: {
      de: "Khan el-Zeit ist eine historische Straße und ein Basar in der Altstadt von Jerusalem, der für seine traditionellen Öl- und Lebensmittelgeschäfte bekannt ist.",
      hu: "A Khan el-Zeit Jeruzsálem óvárosának történelmi utcája és bazára, amely hagyományos olaj- és élelmiszerboltjairól híres.",
      ro: "Khan el-Zeit este o stradă istorică și un bazar în Orașul Vechi din Ierusalim, faimos pentru magazinele de ulei și alimente.",
      en: "Khan el-Zeit is a historic street and bazaar in the Old City of Jerusalem, renowned for its traditional oil and food shops.",
      es: "Khan el-Zeit es una calle histórica y un bazar en la Ciudad Vieja de Jerusalén, conocido por sus tiendas tradicionales de aceite y alimentos.",
      pt: "Khan el-Zeit é uma rua histórica e um bazar na Cidade Velha de Jerusalém, conhecido pelas suas lojas tradicionais de azeite e alimentos.",
      fr: "Khan el-Zeit est une rue historique et un bazar dans la vieille ville de Jérusalem, connu pour ses boutiques traditionnelles d'huile et de nourriture.",
    },
    facts: {
      de: ["Bedeutet Markt des Öls", "Teil des koptischen Viertels", "Lebhafte Marktatmosphäre", "Mittelalterliche Steinbögen"],
      hu: ["Jelentése: az Olaj piaca", "A kopt negyed része", "Élénk piaci hangulat", "Középkori kőboltozatok"],
      ro: ["Înseamnă Piața Uleiului", "Parte a cartierului copt", "Atmosferă vibrantă de piață", "Arcade de piatră medievale"],
      en: ["Name translates to 'Market of Oil'", "Part of the route to the Holy Sepulchre", "Vibrant market atmosphere", "Features medieval stone vaulting"],
      es: ["Significa Mercado del Aceite", "Parte del barrio copto", "Atmósfera de mercado animada", "Arcos de piedra medievales"],
      pt: ["Significa Mercado do Azeite", "Parte do bairro copta", "Atmosfera de mercado animada", "Arcos de pedra medievais"],
      fr: ["Signifie Marché de l'huile", "Fait partie du quartier copte", "Atmosphère de marché animée", "Arches médiévales en pierre"],
    },
    imageHint: "Khan el-Zeit market street Jerusalem",
    descriptionAdvanced: {
      de: "Khan el-Zeit ist eine der lebendigsten und historisch bedeutsamsten Straßen im christlichen und muslimischen Viertel der Altstadt von Jerusalem. Der Name, der übersetzt „Markt des Öls“ bedeutet, erinnert an die Zeit, als hier vor allem Olivenöl und daraus hergestellte Produkte gehandelt wurden. Heute ist die Straße ein pulsierender Basar, auf dem Besucher alles von Gewürzen über traditionelle Süßigkeiten bis hin zu handgefertigten Haushaltswaren finden können. Architektonisch ist Khan el-Zeit geprägt durch beeindruckende mittelalterliche Steinbögen und Gewölbe, die teilweise aus der Zeit der Kreuzfahrer und der Mamluken stammen. Die Straße ist zudem ein wichtiger Teil des Pilgerweges, der zur Grabeskirche führt, und spiegelt die vielschichtige religiöse und kulturelle Identität Jerusalems wider. Das ständige Treiben der Händler, die Rufe der Verkäufer und die intensiven Düfte machen einen Spaziergang durch Khan el-Zeit zu einem Erlebnis für alle Sinne, das tief in den Alltag der Stadt eintauchen lässt.",
      hu: "A Khan el-Zeit Jeruzsálem óvárosának egyik legforgalmasabb és leghangulatosabb utcája, amely a kopt és a muszlim negyeden halad keresztül. Az utca neve arabul „Olajpiacot” jelent, utalva arra a történelmi időszakra, amikor ez a terület volt az olívaolaj-kereskedelem központja a városban. A mai napig megőrizte bazár jellegét, ahol a látogatók a fűszerek, édességek, ruhaneműk és kézműves termékek végtelen választékával találkozhatnak. Az építészet hűen tükrözi a múltat: a középkori kőboltozatok és a mamlúk korból származó épületek különleges atmoszférát árasztanak. Khan el-Zeit fontos állomása a Szent Sír-templom felé tartó zarándokoknak is, így a vallási turizmus és a helyi kereskedelem itt fonódik össze legszorosabban. Az utca lüktetése, az árusok kiáltozása és a frissen őrölt kávé illata felejthetetlen élményt nyújt mindazoknak, akik szeretnének belelátni Jeruzsálem mindennapi, mégis történelmi arcába.",
      ro: "Khan el-Zeit este una dintre cele mai efervescente artere comerciale din Orașul Vechi al Ierusalimului, străbătând cartierele creștin și musulman. Numele său se traduce prin „Piața Uleiului”, amintind de perioada în care strada era centrul principal pentru comerțul cu ulei de măsline și produse derivate. Astăzi, strada s-a transformat într-un bazar vibrant, unde vizitatorii pot descoperi o multitudine de mărfuri, de la mirodenii exotice și dulciuri tradiționale, până la obiecte de artizanat și îmbrăcăminte. Arhitectura străzii este marcată de arcade medievale de piatră și bolți impunătoare, martore ale epocilor mamelucă și cruciată. Fiind o rută esențială pentru pelerinii care se îndreaptă spre Biserica Sfântului Mormânt, Khan el-Zeit reprezintă un punct de întâlnire cultural și religios unic. Atmosfera este întotdeauna animată de forfota cumpărătorilor și de aromele intense ale bucătăriei locale, oferind o perspectivă autentică asupra vieții cotidiene într-un oraș cu o istorie de mii de ani.",
      en: "Khan el-Zeit is one of the most vibrant and historically significant thoroughfares within the Old City of Jerusalem, stretching through the heart of the Christian and Muslim Quarters. Its name, which means 'Market of Oil,' dates back to a time when it was the city's primary hub for the sale of olive oil and related products. Today, it remains a bustling bazaar where visitors can find everything from aromatic spices and traditional Arabic sweets to handmade textiles and souvenirs. The street is architecturally striking, featuring ancient stone vaulting and medieval archways that reflect the city's Mamluk and Crusader heritage. As a major artery leading toward the Church of the Holy Sepulchre, Khan el-Zeit is constantly filled with a mix of local residents, pilgrims, and tourists. The sensory experience of walking through the market—with its rhythmic sounds of trade and the rich scents of Middle Eastern cuisine—offers an authentic glimpse into the enduring cultural tapestry of Jerusalem.",
      es: "Khan el-Zeit es una de las calles comerciales más concurridas de la Ciudad Vieja de Jerusalén y conduce desde la Puerta de Damasco hacia los barrios cristiano y musulmán. Su nombre significa 'Posada del Aceite' y hace referencia a la importancia histórica del comercio de aceite de oliva en esta zona. La calle está llena de pequeñas tiendas, puestos de comida y edificios históricos que reflejan la vibrante atmósfera de Oriente.",
      pt: "Khan el-Zeit é uma das ruas de mercado mais movimentadas da Cidade Velha de Jerusalém e leva da Porta de Damasco aos bairros cristão e muçulmano. O nome significa 'Hospedaria do Azeite' e refere-se à importância histórica do comércio de azeite nesta área. A rua é ladeada por pequenas lojas, bancas de comida e edifícios históricos que refletem a atmosfera vibrante do Oriente.",
      fr: "Khan el-Zeit est l'une des rues commerçantes les plus animées de la vieille ville de Jérusalem, menant de la porte de Damas aux quartiers chrétien et musulman. Le nom signifie « auberge de l'huile » et souligne l'importance historique du commerce de l'huile d'olive dans cette zone. La rue est bordée de petites boutiques, de stands de nourriture et de bâtiments historiques qui reflètent l'atmosphère vibrante de l'Orient.",
    },
